<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="theme-color" content="#19191e">
<meta name="description" content="Dune Line: an overnight rail passage from Sable Junction to the neon streets of Lumen City. Explore nightly departures and plan your crossing.">
<link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 40 40'%3E%3Crect width='40' height='40' rx='8' fill='%23d9f793'/%3E%3Cpath d='M5 28 17 10h6L11 28zm10 0 12-18h6L21 28z' fill='%2319191e'/%3E%3C/svg%3E">
<title>Dune Line — The Overnight Express</title>
<style>
:root {
  color-scheme: dark;
  --ink:#19191e; --panel:#212126; --paper:#f3eee2; --muted:#bbb7b2;
  --lime:#d9f793; --peach:#ffb493; --line:#404046;
  --sans:Arial,Helvetica,sans-serif;
  --serif:Georgia,"Times New Roman",serif;
  --mono:"SFMono-Regular",Consolas,"Liberation Mono",monospace;
}
*,*::before,*::after{box-sizing:border-box}
html{scroll-behavior:smooth;scroll-padding-top:22px}
body{margin:0;background:var(--ink);color:var(--paper);font:16px/1.55 var(--sans);-webkit-font-smoothing:antialiased}
button,a,select{font:inherit}
button,a{touch-action:manipulation}
button{cursor:pointer}
a{color:inherit;text-decoration:none}
button{color:inherit}
figure,p,h1,h2,h3,blockquote{margin:0}
svg{display:block}
::selection{background:var(--lime);color:var(--ink)}
:focus-visible{outline:3px solid #84acfa;outline-offset:5px}
.wrap{width:min(1420px,90%);margin-inline:auto}
.mono,.eyebrow{font-family:var(--mono);font-weight:500;text-transform:uppercase;letter-spacing:.115em}
.eyebrow{font-size:10px;line-height:1.5;display:flex;align-items:center;gap:13px}
.eyebrow .index{color:var(--lime)}
.eyebrow .rule{width:27px;border-top:1px solid currentColor;opacity:.6}
.skip{position:absolute;z-index:10;left:1rem;top:-100px;background:var(--lime);color:var(--ink);padding:10px 16px}
.skip:focus{top:8px}
.site-head{border-bottom:1px solid var(--line)}
.navbar{height:81px;display:flex;align-items:center;gap:38px;position:relative}
.brand{display:inline-flex;align-items:center;gap:10px;font-size:27px;font-weight:750;letter-spacing:-1.8px;line-height:1}
.brand svg{width:39px;height:29px;color:var(--lime)}
nav{display:flex;gap:30px;margin-left:auto}
nav a,.footer-link{font-size:13px;color:#d2cfc9}
nav a:hover,.footer-link:hover{color:var(--lime)}
.nav-cta,.menu-btn{background:transparent;border:1px solid #68676a;border-radius:4px;font-size:13px;padding:9px 16px;font-weight:600}
.nav-cta span{margin-left:12px;color:var(--lime)}
.nav-cta:hover,.menu-btn:hover{border-color:var(--lime)}
.menu-btn{display:none}
.hero{display:grid;grid-template-columns:.88fr 1.12fr;gap:clamp(28px,4vw,70px);align-items:center;padding-block:clamp(42px,4.2vw,66px)}
.hero-copy{padding-block:10px}
.hero-label{color:var(--lime);gap:10px}
.signal{width:7px;height:7px;background:var(--lime);border-radius:50%;box-shadow:0 0 0 4px #d9f79312;margin:0 4px}
h1{font-size:clamp(66px,6.9vw,108px);line-height:.99;letter-spacing:-.077em;font-weight:600;margin:28px 0 24px}
h1 em{display:inline-block;font-family:var(--serif);font-size:1.09em;line-height:1;font-weight:400;letter-spacing:-.075em;color:var(--peach)}
.hero-copy>p{max-width:380px;color:#c9c5c1;font-size:clamp(16px,1.35vw,19px);line-height:1.6}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:27px;background:var(--lime);color:var(--ink);border:1px solid transparent;border-radius:4px;padding:13px 18px;font-size:14px;font-weight:650;line-height:1.3;transition:background .15s,transform .15s}
.btn:hover{background:#e5ffad;transform:translateY(-2px)}
.hero .btn{margin-top:29px}
.arrow{font-weight:400;font-size:1.18em;line-height:1}
.hero-meta{margin-top:24px;display:flex;gap:10px;align-items:center;font-size:10px;letter-spacing:.055em;color:#bdb9b6}
.hero-meta i{width:3px;height:3px;border-radius:50%;background:#8d898c}
.plate{border:1px solid #62606b;background:#26242f;border-radius:5px;overflow:hidden;position:relative}
.landscape{width:100%;height:auto}
.plate figcaption{background:#26252b;border-top:1px solid #655a61;padding:13px 17px;display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:9px;letter-spacing:.12em;color:#d7d0c7}
.fig-no{color:var(--peach)}
.small-stars{color:var(--peach);letter-spacing:.28em}
.experience{padding:23px 0 34px;border-top:1px solid var(--line)}
.experience>.eyebrow{color:#c9c5c0}
.features{display:grid;grid-template-columns:repeat(3,1fr);margin-top:25px}
.feature{display:grid;grid-template-columns:40px 1fr;gap:16px;padding:0 clamp(15px,2.5vw,40px);border-left:1px solid var(--line)}
.feature:first-child{padding-left:0;border:0}
.feature:last-child{padding-right:0}
.feature svg{color:var(--peach);width:38px;height:38px}
.feature h3{font-size:19px;font-weight:550;line-height:1.25;letter-spacing:-.035em;margin-bottom:7px}
.feature p{font-size:14px;line-height:1.55;color:var(--muted);max-width:290px}
.schedule{background:var(--paper);color:var(--ink);padding:64px 0 60px;position:relative}
.schedule .index{color:#78533f}
.section-head{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;margin:15px 0 30px}
h2{font-size:clamp(38px,4.1vw,64px);line-height:1.08;font-weight:550;letter-spacing:-.065em}
h2 em{font-family:var(--serif);font-weight:400}
.route{display:flex;align-items:center;gap:10px;font-size:12px;margin-bottom:4px}
.route svg{width:48px}
.board{border-top:2px solid var(--ink)}
table{width:100%;border-collapse:collapse;text-align:left}
th{font:10px/1.4 var(--mono);letter-spacing:.09em;text-transform:uppercase;color:#615e5a;padding:13px 0;border-bottom:1px solid #bebbb3}
td{border-bottom:1px solid #c9c5bb;padding:17px 0}
th:first-child{width:26%}
th:nth-child(2),th:nth-child(3){width:23%}
.time{font:500 clamp(20px,2.1vw,31px)/1.2 var(--mono);letter-spacing:-.065em}
.time small{font:10px var(--mono);vertical-align:super;margin-left:5px;letter-spacing:0;color:#655e59}
.train-id{display:inline-block;padding:2px 6px;border:1px solid #b2aaa0;border-radius:2px;font:12px var(--mono);letter-spacing:.04em}
.frequency{font-size:14px}
.choose{text-align:right}
.row-btn{height:34px;width:42px;border-radius:20px;background:none;border:1px solid #a69f95;color:var(--ink);font-size:18px;line-height:1}
.row-btn:hover{background:var(--ink);color:var(--paper)}
.board-note{margin-top:15px;font:10px/1.6 var(--mono);color:#625c55;letter-spacing:.025em}
.fares{padding-block:65px}
.fares .section-head p{color:var(--muted);font-size:14px}
.tickets{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}
.ticket{--edge:#48474c;position:relative;display:flex;flex-direction:column;background:var(--panel);border:1px solid var(--edge);border-radius:6px;overflow:hidden}
.ticket.featured{--edge:#849367;background:#252a24}
.ticket-main{padding:24px 25px 22px;flex:1}
.ticket-label{display:flex;align-items:center;justify-content:space-between;gap:6px;font-size:10px;color:#bfbcb7;min-height:22px}
.badge{background:var(--lime);color:var(--ink);padding:3px 7px;border-radius:2px;font-size:9px;letter-spacing:.06em}
.ticket h3{font-size:26px;letter-spacing:-.045em;line-height:1.2;margin:15px 0 9px;font-weight:550}
.ticket p{font-size:14px;line-height:1.6;color:#c2bfba;max-width:30ch}
.ticket-price{display:flex;align-items:baseline;gap:8px;margin-top:22px}
.ticket-price strong{font:italic 43px/1 var(--serif);letter-spacing:-.07em}
.ticket-price span{font:10px var(--mono);color:#c1bcb5}
.tear{position:relative;border-top:1px dashed #625f61}
.tear:before,.tear:after{content:"";position:absolute;top:-8px;width:14px;height:14px;background:var(--ink);border:1px solid var(--edge);border-radius:50%}
.tear:before{left:-8px}.tear:after{right:-8px}
.ticket-action{padding:16px 25px}
.ticket-action button{display:flex;align-items:center;justify-content:space-between;border:0;background:none;width:100%;padding:4px 0;color:var(--paper);font-size:14px;text-align:left}
.ticket-action button:hover{color:var(--lime)}
.featured .ticket-action button{color:var(--lime)}
.review{border-block:1px solid var(--line);padding:43px 0;display:grid;grid-template-columns:1fr 2.5fr;align-items:start;gap:25px}
.review .eyebrow{margin-top:7px}
blockquote p{font:italic clamp(25px,2.7vw,42px)/1.25 var(--serif);letter-spacing:-.045em;color:var(--peach);max-width:32ch}
blockquote cite{display:block;font:10px/1.6 var(--mono);text-transform:uppercase;letter-spacing:.09em;margin-top:18px;color:var(--muted)}
footer{display:flex;align-items:center;justify-content:space-between;gap:20px;padding-block:31px}
footer .brand{font-size:21px}
footer .brand svg{width:29px}
footer p{font-size:10px;color:var(--muted);letter-spacing:.045em}
dialog{color:var(--ink);background:var(--paper);width:min(440px,calc(100% - 32px));max-height:90dvh;padding:30px;border:1px solid var(--ink);border-radius:7px;box-shadow:0 24px 90px #0006}
dialog::backdrop{background:#101117c9}
.dialog-top{display:flex;align-items:center;justify-content:space-between;margin-bottom:20px}
.dialog-top .eyebrow{color:#655d54}
.close{width:34px;height:34px;background:none;border:1px solid #bcb5aa;border-radius:50%;font-size:20px;line-height:1}
dialog h2{font-size:38px;margin-bottom:12px}
dialog p{font-size:14px;color:#5c5854;margin-bottom:19px}
dialog label{font:11px var(--mono);text-transform:uppercase;letter-spacing:.09em;display:block;margin:17px 0 7px}
dialog select{color-scheme:light;width:100%;padding:11px;background:#fffaf1;border:1px solid #b3aba0;border-radius:3px;font-size:14px;color:var(--ink)}
dialog .btn{width:100%;margin-top:23px;border-color:var(--ink)}
.trip-details{margin:18px 0 0;border-top:1px dashed #9b9181}
.trip-details div{display:flex;justify-content:space-between;gap:12px;padding:10px 0;border-bottom:1px solid #cfc7bb;font-size:14px}
.trip-details dt{color:#656057}.trip-details dd{margin:0;text-align:right;font-weight:600}
@media(min-width:1550px){.hero-copy>p{max-width:440px}.hero-copy{padding-left:10px}}
@media(max-width:1000px){
  .wrap{width:92%}.hero{gap:24px;grid-template-columns:.91fr 1.09fr}
  h1{font-size:clamp(58px,7.1vw,75px);margin:22px 0 17px}
  .hero-meta{font-size:9px}.feature{gap:10px;grid-template-columns:32px 1fr}.feature svg{width:30px}
  .ticket-main{padding:20px}.tickets{gap:12px}
}
@media(max-width:760px){
  .wrap{width:calc(100% - 40px)}.navbar{height:65px;gap:10px}.brand{font-size:24px}
  .menu-btn{display:block;margin-left:0;padding:8px 10px}.nav-cta{margin-left:auto;padding:8px 11px}
  nav{display:none;position:absolute;z-index:5;top:calc(100% - 1px);right:0;left:0;background:#24242a;border:1px solid var(--line);border-radius:0 0 5px 5px;padding:6px}
  nav.open{display:grid;gap:0}nav a{padding:11px 13px}
  .hero{grid-template-columns:1fr;gap:28px;padding-block:35px 30px}
  .hero-copy{padding:0}.hero-label{font-size:9px}
  h1{font-size:clamp(63px,11vw,86px);margin:23px 0 18px}.hero-copy>p{max-width:440px}
  .hero .btn{margin-top:21px}.hero-meta{margin-top:17px}
  .plate{width:100%}.experience{padding-bottom:26px}.features{grid-template-columns:1fr;gap:19px;margin-top:20px}
  .feature,.feature:first-child{border:0;padding:0;gap:15px;grid-template-columns:34px 1fr}
  .feature h3{margin-bottom:3px}.feature p{max-width:none}
  .section-head{align-items:flex-start;flex-direction:column;gap:13px;margin-bottom:22px}
  .schedule,.fares{padding-block:40px}
  th:first-child{width:24%}.frequency,th.frequency-head{display:none}
  th{font-size:9px}td{padding-block:14px}.train-id{font-size:10px}
  .time{font-size:23px}.time small{font-size:8px;margin-left:2px}
  .tickets{grid-template-columns:1fr;gap:15px}.ticket-main{padding:21px}
  .ticket p{max-width:100%}.ticket-action{padding:12px 21px}
  .review{grid-template-columns:1fr;gap:19px;padding-block:30px}
  footer{flex-wrap:wrap;gap:15px}footer p{order:1;width:100%}
}
@media(max-width:365px){.nav-cta span{display:none}.wrap{width:calc(100% - 30px)}.brand{gap:6px}.brand svg{width:30px}.time{font-size:20px}.plate figcaption{font-size:8px;padding:10px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*::before,*::after{transition:none!important}}
</style>
</head>
