    nav.classList.toggle('open', open);
    menu.setAttribute('aria-expanded', String(open));
    menu.textContent = open ? 'Close' : 'Menu';
  }
  menu.addEventListener('click', () => setMenu(!nav.classList.contains('open')));
  nav.addEventListener('click', () => setMenu(false));
  document.addEventListener('keydown', e => {
    if (e.key === 'Escape' && nav.classList.contains('open')) { setMenu(false); menu.focus(); }
  });

  const dialog = $('planner'), form = $('plan-form'), preview = $('preview');
  const service = $('service'), fare = $('fare'), title = $('planner-title');
  const arrivals = {101:'05:50',103:'07:20',105:'08:40',107:'09:55'};
  function editPlan() {
    form.hidden = false;
    preview.hidden = true;
    title.textContent = 'Plan your crossing.';
  }
  document.querySelectorAll('[data-plan]').forEach(button => {
    button.addEventListener('click', () => {
      setMenu(false);
      if (button.dataset.service) service.value = button.dataset.service;
      if (button.dataset.fare) fare.value = button.dataset.fare;
      editPlan();
      dialog.showModal();
      document.body.style.overflow = 'hidden';
      service.focus();
    });
  });
  dialog.querySelector('.close').addEventListener('click', () => dialog.close());
  dialog.addEventListener('close', () => { document.body.style.overflow = ''; });
  dialog.addEventListener('click', e => {
    const r = dialog.getBoundingClientRect();
    if (e.target === dialog && (e.clientX < r.left || e.clientX > r.right || e.clientY < r.top || e.clientY > r.bottom)) dialog.close();
  });
  form.addEventListener('submit', e => {
    e.preventDefault();
    $('out-service').textContent = 'DL—' + service.value;
